 for en,zh,pg in [('Broodlord','族群领主','GW-09中文37页；GW-10英文36页'),('Redemptor Dreadnought','救赎者无畏机甲','GW-09中文33页；GW-10英文32页')]:f.write('\t'.join([en,zh,'官方已核对','GW-09 https://assets.warhammer-community.com/chi_06-05_wh40k_core%26key_munitorum_field_manual-5mrlucr2t1-fkybzzzoce.pdf；GW-10 https://assets.warhammer-community.com/eng_warhammer40000_munitorum_field_manual_march_2025-cims9ya3sg-s8j9m2haae.pdf',pg,'对应中英同名单位，已直接核读。'])+'\n')
